TP.register({id:"lp6-g2",lp:6,grade:"2",mode:"curriculum",checks:5,nextGrade:"3rd grade",build(E){const F=E.F;const NIGHT_WALK="Juno woke before anyone else in the house. She pulled on two sweaters. Then she carried the last paper lantern down to the river. All week the crew had strung ropes across the main street. Juno had watched from the window. Tonight every lantern was lit but one. The rope sagged in the middle. So she stood on a crate to reach the empty hook. Her hands shook in the cold. She hung the lantern, stepped down, and looked up. The whole street glowed above her. Down in the black water the lights floated too. It looked as if the river had a street of its own.";const TWINKLE="A star does not blink. Far out in space it shines with a steady light. The twinkle happens much closer to you, in the air above your head. Air is always moving. Warm air bends light a little more than cold air does. The moving air slides past. The thin beam of starlight bends this way and that. From the ground the star seems to jump and flicker. A planet looks steadier. A planet is close enough to show a tiny disk. It shows a disk instead of a single point. Astronauts above the air see stars that do not twinkle at all.";const HOW_MADE="A paper lantern is mostly air. A thin paper shell is stretched over a frame of split bamboo, and a small light sits inside on a metal cup. The paper spreads the light out, so the whole lantern glows instead of one bright point. White paper gives a cool light, and red paper gives a warm one. Because the frame folds flat, a hundred lanterns can be carried in one box and opened again the next year. A lantern maker can finish about ten of them in a day.";const WORDS=["glowed","bright","porch","stream","shout","knew","moonlight","relight","quietly","could","spleet","blorn"];const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>{const eye=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`;const blush=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`;const smile=(x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`;return eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4)});const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",ROSE="#F7A8A0",GOLDL="#FBD873",BRASS="#D9A066",NIGHT="#453F80",STARC="#FBF3D6";function lanternShape(x,y,s,c){return TP_LANT(x,y,s/44,c,false)}const lanternSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.5)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a paper lantern">${lanternShape(w*.5,w*.78,w*.9,c)}</svg>`;function ropeRow(n){const w=620,h=150,x0=40,x1=w-40,sag=22,ry=x=>{const t=(x-x0)/(x1-x0);return 44+4*sag*t*(1-t)};let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${NIGHT}" stroke="var(--line)" stroke-width="4"/>`;let s=17;const rnd=()=>{s=(s*9301+49297)%233280;return s/233280};for(let i=0;i<6;i++)b+=`<circle cx="${(18+rnd()*(w-36)).toFixed(0)}" cy="${(14+rnd()*24).toFixed(0)}" r="2.2" fill="${STARC}" opacity=".85"/>`;b+=`<path d="M${x0} 44 Q${(x0+x1)/2} ${44+2*sag} ${x1} 44" fill="none" stroke="${INK}" stroke-width="5" stroke-linecap="round"/>`;const cols=[ROSE,GOLDL,"#C9A6EC","#9FD6F0","#F6B3D0"];for(let i=0;i<n;i++){const x=x0+(i+.5)*(x1-x0)/n;b+=lanternShape(x,ry(x)+26,44,cols[i%5])}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A rope across the street with ${n} paper lanterns hanging from it">${b}</svg>`}const LOG=F.table(["Night","Lanterns hung","Weather"],[["Monday","24","clear"],["Tuesday","31","windy"],["Wednesday","18","rain"],["Thursday","29","clear"]],{caption:"Lantern Crew Log"});const CLOCKS=[["A",7,5],["B",8,30],["C",2,45],["D",11,20]];function clockRow(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS.map(c=>`<div>${F.clock(c[1],c[2],210)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}const VIOLET="#C9A6EC",BLUE2="#9FD6F0",GREEN2="#9CD3A4";const lab2=(x,y,t,sz)=>`<text x="${x}" y="${y}" font-size="${sz||22}" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${t}</text>`;const TWO_LANTERNS="A brand new lantern hung beside an old one on the rope. My paper is bright red, said the new lantern. Everyone will look at me, not at you. That night the wind came hard. The new lantern was tied with one quick knot. It slipped and hung down crooked. Its light was pointing at the ground. The old lantern was tied with three careful knots. It stayed up straight and lit the whole street until morning.";function oddEvenFig(){const w=660,h=250;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<path d="M330 20 V208" stroke="var(--line)" stroke-width="3"/>`;for(let i=0;i<14;i++)b+=lanternShapeS(36+i%7*42,58+Math.floor(i/7)*72,38,GOLDL);b+=lab2(166,224,"Group A");for(let i=0;i<9;i++)b+=lanternShapeS(372+i%5*42,58+Math.floor(i/5)*72,38,ROSE);b+=lab2(466,224,"Group B");return`<svg viewBox="0 0 ${w} ${h}" width="640" role="img" aria-label="Group A has two rows of seven gold lanterns, so every lantern has a partner below it. Group B has a top row of five pink lanterns and a bottom row of four, so one lantern in the top row has no partner.">${b}</svg>`}function arrayFig(rows,cols){const cell=62,w=cols*cell+24,h=rows*cell+24;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)b+=lanternShape(12+c*cell+cell/2,12+r*cell+cell/2,46,r%2?ROSE:GOLDL);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,520)}" role="img" aria-label="${rows} rows of ${cols} paper lanterns laid out on the cart">${b}</svg>`}const COLOR_ROWS=[["Gold",7,GOLDL],["Rose",5,ROSE],["Violet",4,VIOLET]];function colorGraph(){const w=580,h=258;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<path d="M108 22 V208" stroke="var(--line)" stroke-width="3"/>`;COLOR_ROWS.forEach((r,i)=>{const y=54+i*62;b+=`<text x="96" y="${y}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="end" dominant-baseline="central">${r[0]}</text>`;for(let k=0;k<r[1];k++)b+=lanternShapeS(126+k*62,y,46,r[2])});b+=`<text x="${w/2}" y="236" font-size="19" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)" text-anchor="middle">Each lantern picture stands for 1 lantern.</text>`;return`<svg viewBox="0 0 ${w} ${h}" width="560" role="img" aria-label="A picture graph of lantern colors on one rope. The gold row has seven lantern pictures, the rose row has five, and the violet row has four. Each picture stands for one lantern.">${b}</svg>`}function shapesFig2(){const st=`stroke="${INK}" stroke-width="3.4" stroke-linejoin="round"`;const w=760,h=230;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<polygon points="96,40 150,150 42,150" fill="${GOLDL}" ${st}/>`+lab2(96,192,"Shape A");b+=`<polygon points="246,46 338,46 316,150 268,150" fill="${ROSE}" ${st}/>`+lab2(292,192,"Shape B");b+=`<polygon points="470,38 524,78 504,142 436,142 416,78" fill="${BLUE2}" ${st}/>`+lab2(470,192,"Shape C");b+=`<polygon points="660,38 706,64 706,116 660,142 614,116 614,64" fill="${GREEN2}" ${st}/>`+lab2(660,192,"Shape D");return`<svg viewBox="0 0 ${w} ${h}" width="720" role="img" aria-label="Four flat shapes. Shape A has three sides. Shape B has four sides. Shape C has five sides. Shape D has six sides.">${b}</svg>`}const STOPS=[{id:1,title:"Lantern Word Flip",short:"Night Words",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:95,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with silent e, vowel teams, r-controlled vowels, two syllables, a prefix, a suffix, and an irregular spelling",key:["Read each word in order. spleet and blorn are made-up words: listen for the ee team sound and the or sound.","Watch for: the -ed ending said as /d/ (glowed), igh (bright), r-controlled or plus ch (porch), a three-letter blend with ea (stream), the ou diphthong (shout), silent k with ew (knew), a compound word (moonlight), the prefix re- (relight), the suffix -ly (quietly), an irregular spelling (could)."]}]},{id:2,title:"Hang the Lanterns",short:"Hang Them",parts:[{std:["2.OA.A.1"],dur:150,dir:"Read each problem with your teacher. Solve it on your paper. You can draw or write a number sentence. Say your answer.",desc:"one-step addition and subtraction word problems within 100 with the unknown in different places",html:()=>`<div class="figure">${ropeRow(6)}</div><p class="big" style="margin-top:0">The lantern crew hangs paper lanterns on ropes across the main street.</p>`,qs:["A rope holds 45 lanterns. So far 28 of them are lit. How many are not lit yet?","River Street got 34 lanterns and Pine Street got 29. How many lanterns is that in all?","River Street has 26 lanterns. Pine Street has 18 more lanterns than River Street. How many does Pine Street have?","Some lanterns were on the cart. The crew hung 37 of them. Now 16 are left on the cart. How many were on the cart at first?","There were 61 candles in the box. The crew used 48 of them. How many candles are left?"],key:["17 lanterns (28 + a box = 45, or 45 - 28 = 17)","63 lanterns (34 + 29 = 63)","44 lanterns (26 + 18 = 44)","53 lanterns (a box take away 37 is 16, or 16 + 37 = 53)","13 candles (61 - 48 = 13)"]}]},{id:3,title:"The Last Lantern",short:"Last One",parts:[{title:"Read the Story",std:["RF.2.4"],kind:"read",n:105,label:"words read correctly",dur:90,dir:"Read the story out loud. Use your best reading voice.",desc:"a 105-word grade-level story read aloud",html:()=>`<p class="passage g2-flu">${NIGHT_WALK}</p>`,key:["105 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]},{title:"Story Questions",std:["RL.2.1"],dur:80,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering who, what, why, and how questions about key details in a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>The Last Lantern (click to open or close the story)</summary><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${NIGHT_WALK}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-flu"))d.open=false},qs:["Who carried the last lantern down to the river?","What did she put on before she went out?","Why did she have to stand on a crate?","How did the street look after she hung the lantern?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["Juno","Two sweaters","The rope sagged in the middle, so the empty hook was too high for her to reach.","The whole street glowed above her, and the lights showed in the black water too.","Asks a question that is about this story and starts with a question word (for example: When did Juno wake up? Where was the empty hook?)."]}]},{id:4,title:"Boxes, Ropes, and Ones",short:"Place Value",parts:[{std:["2.NBT.A.1"],n:6,dur:100,dir:"Look at the blocks. Answer out loud.",desc:"three-digit place value, including a hundred as ten tens",html:()=>`<p class="big" style="margin-top:0">The crew packs lanterns like this. A flat is a box of 100. A long block is a rope of 10. A small cube is one loose lantern.</p>`,fig:()=>F.row(F.blocks(2,4,3)),qs:["Look at the picture. How many hundreds, tens, and ones are there? What number is that?","A box holds 100 lanterns. How many ropes of ten does it take to fill one box?","In the number 348, what does the 3 stand for?","In the number 507, how many tens are there? How many ones?","The crew has 7 boxes, 2 ropes, and 6 loose lanterns. What number is that?","Which is more, 4 boxes of a hundred or 40 ropes of ten? How do you know?"],key:["2 hundreds, 4 tens, and 3 ones. That is 243","10 ropes. A hundred is the same as ten tens","3 hundreds, which is 300","0 tens and 7 ones. The 0 is holding the tens place","726","They are the same. 4 hundreds is 400, and 40 tens is also 400"]}]},{id:5,title:"Why Stars Twinkle",short:"Twinkle",parts:[{std:["RI.2.1"],dur:80,dir:"Read about stars. Then answer each question out loud.",desc:"asking and answering what, where, why, and who questions about an informational text the student read",html:()=>passage("Why Stars Twinkle",TWINKLE),qs:["What makes a star seem to twinkle?","Where does the twinkle happen?","Why does a planet look steadier than a star?","Who sees stars that do not twinkle at all?","Your turn. Ask a question about stars. Start with who, what, where, when, why, or how."],key:["Moving air bends the thin beam of starlight this way and that","In the air above your head, not out at the star","A planet is close enough to show a tiny disk instead of a single point","Astronauts, because they are above the air","Asks a question that is about the topic and starts with a question word (for example: How far away is the nearest star? Why does warm air bend light more?)."]}]},{id:6,title:"Fix the Crew Note",short:"Crew Note",parts:[{title:"Say It Right",std:["L.2.1"],dur:90,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, word order, joining two sentences)",qs:["Tonight the lanterns shine. Last night they ____.","One child, two ____.","We carried the ladder all by ____.","Which word fits? The rope swung ____ in the wind. Is it gentle or gently?","Mix-up! Put these words in order to make a sentence: <span class=mixrow><b class=mixw>floated</b><b class=mixw>the light</b><b class=mixw>on the river</b></span>","Join these two sentences with the word <b>because</b>: We stood on the bridge. The water held the lights."],key:["shone (shined is also used, but shone is the one to listen for)","children","ourselves","gently","The light floated on the river.","We stood on the bridge because the water held the lights."]},{title:"Write It Right",std:["L.2.2"],dur:90,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in place names, an apostrophe for a possessive and a contraction, a comma in a letter greeting, spelling two patterns)",qs:["Fix this sentence: <b>we walked along pine street to the bear river</b>","The ladder belongs to the crew. Write the missing word: <b>the ____ ladder</b>","This is the start of a letter. Write it and add the missing mark: <b>Dear Juno</b>","Write <b>could not</b> as one short word with an apostrophe.","Listen. Write the word your teacher says.","Listen. Write the second word your teacher says."],key:["We walked along Pine Street to the Bear River. (capital W to start, capital P and capital S in the street name, capital B and capital R in the river name, and a period)","crew’s (apostrophe before the s)","Dear Juno, (comma after Juno)","couldn’t (apostrophe where the o of not comes out)","Say: “Bright. The paper glowed bright and gold.” The student writes bright (igh).","Say: “River. The river held the lights.” The student writes river (two syllables, er at the end)."]}]},{id:7,title:"Count Along the River",short:"Skip Count",parts:[{std:["2.NBT.A.2"],dur:110,dir:"Count out loud.",desc:"counting within 1000 and skip-counting by 5s, 10s, and 100s",html:()=>`<p class="big" style="margin-top:0">The crew hangs a lamp every 5 steps along the river path, so the counting goes 5, 10, 15, and on.</p>`,fig:()=>F.row([F.objects("lamp",6),"Lamps along the path"]),qs:["Skip count by 5s from 65 to 105.","Skip count by 10s from 360 to 430.","Count by ones from 896 to 905.","Skip count by 100s from 180 to 780.","Count back by 10s from 420 to 360."],key:["65, 70, 75, 80, 85, 90, 95, 100, 105. Watch the jump past 95.","360, 370, 380, 390, 400, 410, 420, 430. Watch the jump past 390.","896, 897, 898, 899, 900, 901, 902, 903, 904, 905. Watch the jump past 899.","180, 280, 380, 480, 580, 680, 780","420, 410, 400, 390, 380, 370, 360. Watch the step back past 400."]}]},{id:8,title:"Three Ways to Write It",short:"Three Ways",parts:[{std:["2.NBT.A.3"],n:6,dur:105,dir:"Say the first two answers out loud. Write the rest on your paper and hold it up.",desc:"reading and writing numbers to 1000 as numerals, number names, and expanded form",html:()=>`<p class="big" style="margin-top:0">The crew writes the lantern count three different ways in the logbook.</p>`,qs:["Read this number out loud: 519.","What number is 600 + 30 + 8?","Write 406 using words.","Write <b>three hundred ninety-two</b> as a numeral.","Write 275 in expanded form.","Write 80 + 700 + 4 as one number."],key:["five hundred nineteen","638","four hundred six (no tens, so no ten word goes in)","392","200 + 70 + 5","784 (the parts are out of order on purpose: 700 + 80 + 4)"]}]},{id:9,title:"Logbook Math",short:"Logbook",parts:[{std:["2.NBT.B.7"],dur:150,dir:"Solve each one on your paper. Show your work and hold it up. Say your answer.",desc:"adding and subtracting within 1000 with a place value strategy and relating it to a written method",html:()=>`<p class="big" style="margin-top:0">Every year the crew writes down how many lanterns went up in the whole town.</p>`,qs:["Last year 327 lanterns went up on the east side and 248 on the west side. How many in all? Show how you added.","The town wants 600 lanterns up this year. So far 254 are up. How many more are needed?","The crew made 485 lanterns in the fall and 169 more in the winter. How many did they make in all?","There were 712 lanterns in the store room. The crew took out 358 of them. How many are still in the store room?"],key:["575 lanterns (327 + 248 = 575). Listen for hundreds with hundreds, tens with tens, ones with ones, and for making a new ten.","346 more (600 - 254 = 346). This one needs two decomposes, so watch the work.","654 lanterns (485 + 169 = 654). A new ten and a new hundred are both made here.","354 lanterns (712 - 358 = 354). Two decomposes again."]}]},{id:10,title:"Clock Tower",short:"Clocks",parts:[{title:"Read the Clock",std:["2.MD.C.7"],n:4,dur:140,dir:"Look at each clock. Say the time out loud.",desc:"telling time on an analog clock to the nearest five minutes",html:()=>`<p class="big" style="margin-top:0">The clock on the town hall tower keeps the crew on time.</p>`,fig:()=>clockRow(),key:["Clock A: 7:05, said as seven oh five or five past seven. The minute hand is on the 1, and one number mark is five minutes.","Clock B: 8:30, said as eight thirty or half past eight. Watch for a student who says nine thirty because the hour hand has moved halfway to the 9.","Clock C: 2:45, said as two forty-five or quarter to three. The minute hand is on the 9, which is 45 minutes. The hour hand is almost on the 3, so watch for a student who says three forty-five.","Clock D: 11:20, said as eleven twenty or twenty past eleven."]},{title:"Write the Time",std:["2.MD.C.7"],n:5,dur:100,dir:"Write each answer on your paper and hold it up.",desc:"writing times to the nearest five minutes and using a.m. and p.m.",fig:()=>F.row([F.digital("6:15"),"The digital clock in the crew truck"],[F.clock(3,50,210),"The tower clock later that day"]),qs:["Look at the digital clock. Write that time.","The lanterns go up at that time in the evening. Write the time again and add a.m. or p.m.","Juno wakes up at seven o'clock in the morning. Write that time with a.m. or p.m.","Look at the tower clock. Write that time.","Which one happens in the a.m., eating breakfast or watching the lanterns glow at night?"],key:["6:15","6:15 p.m. (evening is after noon, so it is p.m.)","7:00 a.m.","3:50 (the minute hand is on the 10, which is 50 minutes, and the hour hand is almost on the 4)","Eating breakfast. A.m. is from midnight to noon."]}]},{id:11,title:"A New Year Story",short:"Write",parts:[{std:["W.2.3"],n:4,label:"checks met",dur:130,dir:WRITE_DIR,desc:"a short narrative with events in order, details about actions and feelings, time words, and an ending",html:()=>`<p class="big">You are on the lantern crew. You are about to hang the last lantern of the night, and the rope slips out of your hand. Write a story about what happens next. Tell it in order. Tell what you did and how you felt. Write 4 sentences.</p>${pills("First","Then","After that","In the end")}`,key:["Tells about one event or a short set of events in order","Includes details about actions, thoughts, or feelings","Uses time words like first, then, after that, or in the end","Ends with a sentence that wraps up the story"]}]},{id:12,title:"Workshop Report",short:"Report",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:65,read:HOW_MADE,dir:"Listen first. Then answer your teacher's questions out loud.",desc:"recounting and describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ic("ear",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read a report from the lantern workshop.</p>`,key:["Ask: What is a paper lantern made of? (a thin paper shell stretched over a frame of split bamboo, with a small light inside on a metal cup)","Ask: Describe why the whole lantern glows instead of one bright point. (the paper spreads the light out)","Ask: Why can a hundred lanterns fit in one box? (the frame folds flat)","Say: Tell me two more things you learned. (any two: a lantern is mostly air, white paper gives a cool light, red paper gives a warm one, a maker can finish about ten in a day, the lanterns are opened again the next year)"]},{title:"Tell Me About It",std:["SL.2.4"],n:4,label:"checks met",dur:50,dir:"Tell about it out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with facts and details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you stayed up later than usual, or a time you were outside after dark. Where were you? What did you do? What did you see or hear?</p>${pills("First","Next","Last")}`,key:["Tells what happened in an order that makes sense","Gives facts that fit (where, when, who, or what)","Uses describing details (how it looked, felt, or sounded)","Speaks in complete sentences, loud and clear enough to hear"]}]},{id:13,title:"The Crew Log",short:"Crew Log",parts:[{std:["W.2.8"],dur:85,dir:"Use the log to answer. Say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a provided log and recalling information from experience to answer questions",html:()=>`<p class="big" style="margin-top:0">The lantern crew writes down how many lanterns went up each night, and what the weather was like.</p>`,fig:()=>F.row([lanternSvg(68,GOLDL),"One lantern"],LOG),qs:["Use the log. Which night did the crew hang the most lanterns?","Which nights were clear?","A friend asks, “Did more lanterns go up on Monday or on Thursday?” Write one sentence that answers your friend. Use the log.","Now use what you remember. Think of a job you have done outside. What was it, and what made it easy or hard? Say it in a sentence."],key:["Tuesday, with 31 lanterns","Monday and Thursday","The sentence says Thursday and uses the numbers from the log (Thursday had 29 and Monday had 24).","Tells one thing remembered from a real job outside, in a sentence that answers the question (for example: I raked leaves, and it was hard because the wind kept moving them.)."]}]},{id:14,title:"Two Ropes at Once",short:"Two Steps",parts:[{std:["2.OA.A.1"],dur:100,dir:"Each problem has two steps. Solve it on your paper and say your answer.",desc:"two-step addition and subtraction word problems within 100",html:()=>`<p class="big" style="margin-top:0">The crew works two ropes at a time, so most nights take two steps to count.</p>`,qs:["The crew had 52 lanterns. They hung 19 on the first rope and 14 on the second rope. How many lanterns are left?","One cart carries 8 crates of lanterns. A second cart carries 9 crates. The crew unloads 6 crates at the bridge. How many crates are still on the carts?","Spot the mistake. There were 70 lanterns on the street. The wind blew out 25, then the crew relit 15 of them. A helper wrote 70 - 25 - 15 = 30. What did the helper do wrong? Fix it."],key:["19 lanterns (19 + 14 = 33, then 52 - 33 = 19)","11 crates (8 + 9 = 17, then 17 - 6 = 11)","The helper took away the 15 relit lanterns instead of adding them back. 70 - 25 = 45, then 45 + 15 = 60 lanterns lit."]}]},{id:15,title:"Read the Signs",short:"Signs",parts:[{std:["RF.2.3"],n:3,dur:55,dir:"Read each line out loud. Sound out any word that is tricky.",desc:"applying grade-level phonics and word-analysis skills to decode words in text",html:()=>`<ol class="qlist" style="font-size:1.6rem;line-height:1.9"><li>The bright lanterns glowed above the crowded street.</li><li>We unpacked eight boxes and relit every flame.</li><li>The river carried the moonlight downstream.</li></ol>`,key:["Line 1: listen for igh in bright, the -ed ending said as /d/ in glowed, the ow diphthong in crowded, and the two syllables in lanterns.","Line 2: listen for the prefix un in unpacked, the -ed ending said as /t/ in unpacked, the irregular eigh in eight, and the prefix re in relit.","Line 3: listen for the r-controlled er in river and carried, the compound words moonlight and downstream, and the ea team in stream."]}]},{id:16,title:"The Two Lanterns",short:"The Lesson",parts:[{std:["RL.2.2"],n:2,dur:65,dir:"Read the short story out loud. Then answer out loud.",desc:"retelling a short fable in order and naming its lesson",html:()=>passage("The Two Lanterns",TWO_LANTERNS),qs:["Retell this story in your own words. Tell what happened first, next, and last.","What is the lesson of this story?"],key:["The retelling has the three parts in order: the new lantern boasted about its bright red paper, the wind came hard that night, and the new lantern slipped crooked while the old one held up straight and lit the street. Two of the three, in order, is a partial retelling. All three, with details, is a complete one.","Careful work lasts, or doing a job well matters more than looking new and bright, or do not boast. Any lesson the student can tie back to the knots or to the boasting counts. Retelling the plot again instead of naming a lesson does not."]}]},{id:17,title:"Two Kinds of Writing",short:"Write Two",parts:[{title:"What Do You Think",std:["W.2.1"],n:4,label:"checks met",dur:60,dir:WRITE_DIR,desc:"a short opinion piece with a topic, an opinion, a reason joined by a linking word, and a closing sentence",html:()=>`<p class="big">You are on the lantern crew. Which job would you rather have? You could be tying the knots. The knots go on the rope. You could carry the ladder down the street. Write 2 or 3 sentences.</p>${pills("I would rather","because","also","That is why")}`,key:["Introduces the topic: which crew job the writing is about (W.2.1)","States an opinion, which job the student would rather have (W.2.1)","Supplies at least one reason that supports the opinion (W.2.1)","Uses a linking word such as because, and, or also, and ends with a concluding sentence (W.2.1)"]},{title:"Tell a Reader",std:["W.2.2"],n:3,label:"checks met",dur:60,dir:WRITE_DIR,desc:"a short informative piece with a topic, facts or a definition, and a closing sentence",html:()=>`<p class="big">Pick one: a paper lantern, the moon, or the river at night. Write 2 or 3 sentences that tell a reader about it. Use facts, or tell what the thing is.</p><div class="figure">${lanternSvg(56,GOLDL)}${ic("moon",52)}${ic("bridge",56)}</div>`,key:["Introduces the topic, so a reader knows what the writing is about (W.2.2)","Uses facts or a definition to develop the point, such as: A paper lantern is a thin paper shell on a bamboo frame. The paper spreads the light out (W.2.2)","Provides a concluding statement, one sentence that ends it (W.2.2)","The workshop report earlier in this game is fair game as a source of facts. Note it if the student used it."]}]},{id:18,title:"Even Rows on the Cart",short:"Even Rows",parts:[{title:"Pairs and Leftovers",std:["2.OA.C.3"],n:3,dur:45,dir:"Look at the two groups. Answer out loud.",desc:"telling odd from even by pairing, and writing an even number as a sum of two equal addends",fig:()=>F.row(oddEvenFig()),qs:["Group A has 14 lanterns. Is 14 even or odd? How can you tell from the picture?","Group B has 9 lanterns. Is 9 even or odd? How can you tell?","Write 14 as two equal numbers added together."],key:["Even. Every lantern in the top row has a partner below it, so they pair up with none left over.","Odd. The top row has 5 and the bottom row has 4, so one lantern in the top row has no partner.","7 + 7 = 14. Saying seven plus seven is enough; the equation written down is a plus."]},{title:"Rows on the Cart",std:["2.OA.C.4"],n:3,dur:45,dir:"Look at the cart. Answer out loud.",desc:"finding the total in a rectangular array and writing it as a sum of equal addends",fig:()=>F.row(arrayFig(3,5)),qs:["How many rows of lanterns are on the cart, and how many lanterns are in each row?","Write an addition sentence that gives the total.","How many lanterns are on the cart in all?"],key:["3 rows, with 5 lanterns in each row.","5 + 5 + 5 = 15. One addend per row. 3 + 3 + 3 + 3 + 3 = 15 also counts, as long as the student says it is one addend for each column.","15 lanterns. Counting them one by one gets the right answer, so count it correct, but note that the equal groups were not used."]}]},{id:19,title:"Measure and Pay",short:"Measure Pay",parts:[{title:"Pick the Tool",std:["2.MD.A.1"],n:4,dur:75,dir:"Look at the ruler. Answer out loud. For the last one, get a real ruler and measure.",mats:["a ruler"],desc:"measuring a length with a ruler, choosing a sensible measuring tool, and measuring a real object with a ruler",fig:()=>F.row(F.ruler({length:6,unit:"in",item:4,itemLabel:"lantern hook"})),qs:["How long is the lantern hook?","How do you know where to line the hook up on the ruler?","The crew wants to measure the whole rope that goes across the main street. Would you pick this 6 inch ruler or a long measuring tape? Why?","Now get a real ruler. Pick up a spoon or a crayon and measure it. How long is it?"],key:["4 inches. The hook starts at 0 and ends at the 4.","The end of the hook goes on the 0, not on the edge of the ruler. Starting at 1 by mistake gives 3 or 5 instead of 4.","The measuring tape. The rope is far longer than 6 inches, so a short ruler would have to be moved many times and the count would drift.","Picks up the ruler, lines one end of the object up with the 0, reads the nearest whole inch or centimeter, and says the unit."]},{title:"Count the Coins",std:["2.MD.C.8"],n:3,dur:50,dir:"Look at the coins. Answer out loud.",desc:"solving word problems with coins, using the cent symbol",fig:()=>F.coins(["D","D","N","P","P","P"]),qs:["How much money is this in all? Say it in cents.","A sheet of lantern paper costs 45 cents. You pay with 2 quarters. How much change do you get back?","Which is more, 3 dimes or 5 nickels? How much more?"],key:["28 cents, written 28¢. Two dimes make 20¢, the nickel makes 25¢, and the three pennies make 28¢.","5 cents, written 5¢. Two quarters is 50¢, and 50 - 45 = 5.","3 dimes, by 5 cents. 3 dimes is 30¢ and 5 nickels is 25¢, and 30 - 25 = 5."]}]},{id:20,title:"Lantern Colors and Shapes",short:"Graph Shapes",parts:[{title:"Color Graph",std:["2.MD.D.10"],n:3,dur:50,dir:"Look at the picture graph. Answer out loud. Then draw on your paper.",desc:"reading a single-unit picture graph, comparing two rows, and drawing a row of a graph",fig:()=>F.row(colorGraph()),qs:["How many gold lanterns are on this rope?","How many more gold lanterns are there than violet ones?","The crew adds 3 more violet lanterns to the rope. Draw the new violet row on your paper and tell me how many pictures are in it."],key:["7 gold lanterns.","3 more (7 - 4 = 3).","7 pictures in the new violet row (4 + 3 = 7). Each picture stands for one lantern, so the row grows by exactly 3 pictures."]},{title:"Count the Sides",std:["2.G.A.1"],n:3,dur:45,dir:"Look at the four shapes. Answer out loud. Then draw on your paper.",desc:"naming flat shapes by their number of sides and angles, and drawing a shape with given attributes",fig:()=>F.row(shapesFig2()),qs:["How many sides does Shape C have, and what is that shape called?","Which shape is a hexagon? How do you know?","On your paper, draw a shape that has 4 sides and 4 angles. What do we call any shape like that?"],key:["5 sides, so it is a pentagon. It has 5 angles too.","Shape D. A hexagon has 6 sides, and Shape D is the one with 6.","Any closed shape with 4 straight sides and 4 angles: a square, a rectangle, or a lopsided four-sided shape. All of them are quadrilaterals. Shape B on the screen is one too."]}]},{id:21,title:"Three Bulbs in the Workshop Window",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">Three flower bulbs were put in jars in the workshop at the start of the year and checked three weeks later.</p>
     <table class="bigTable"><tr><th>Jar</th><th>What it got</th><th>After three weeks</th></tr>
     <tr><td>1</td><td>water touching the roots, on the sunny window ledge</td><td>green shoot 14 centimeters, one bud</td></tr>
     <tr><td>2</td><td>no water, on the sunny window ledge</td><td>roots dry and brown, no shoot</td></tr>
     <tr><td>3</td><td>water touching the roots, in a dark cupboard</td><td>shoot 9 centimeters, almost white, no bud</td></tr></table>
     <div class="figure">${ic("tulip",88)}${ic("sun",88)}</div>`,qs:["Which jar did best, and what did it get?","Jar 3 was watered and still grew 9 centimeters. Why is it almost white and why has it no bud?","You want to test only whether a bulb needs light. Name two things you would keep the same, and name the one thing you would change."],key:["Jar 1, a 14 centimeter green shoot with a bud. It got both water and light.","It was in a dark cupboard with no light. The bulb had food stored inside it, which is why it got tall, but without light it cannot make more food, so it stays white and has nothing spare for a flower.","Keep the same: the same kind of bulb, the same jar, the same amount of water, the same warm room. Change only one thing: one jar on the window ledge and one jar in the cupboard. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves seeds",html:()=>`<p class="big">Down by the river, seeds have tiny hooks. They catch in a dog's thick coat. The dog is passing by. They are carried along the path. Then they work loose and drop.</p>
     <div class="figure">${ic("dog",88)}${ic("herb",88)}</div>
     <p class="big">Draw a model you could really build out of things in a workshop, such as a strip of rough cloth wrapped round a tube, that would catch a hooked seed, hold it while it travels, and let it go.</p>`,qs:["Draw your model. Label the part the seed hooks onto and show how it comes loose again.","Which animal job does your model copy, and why does the seed need to come loose at some point?"],key:["Any model with a rough or looped carrying surface and a way for the seed to work free: rough cloth on a tube, a loop of fabric with a shake, a brush that can be tapped. The two labeled parts are what to look for.","It copies an animal carrying seeds in its coat to a new place. The seed has to come loose or it would never reach the ground, and a seed that never reaches soil cannot grow."]}]},{id:22,title:"The Riverbank and the Stone Wall",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">Two children looked for living things in two places, twenty minutes in each, and wrote down what they found.</p>
     <table class="bigTable"><tr><th>The wet riverbank</th><th>The dry top of the old stone wall</th></tr>
     <tr><td>3 kinds of reed and rush</td><td>2 kinds of lichen</td></tr>
     <tr><td>2 kinds of snail</td><td>1 kind of moss in a crack</td></tr>
     <tr><td>1 frog, 1 heron, 1 water beetle</td><td>1 kind of ant, 1 lizard</td></tr>
     <tr><td>2 kinds of willow</td><td></td></tr></table>
     <div class="figure">${ic("frog",80)}${ic("snail",80)}</div>`,qs:["How many kinds of living things are on the riverbank list?","Which place has more different kinds of living things?","The bank is wet all year and the wall top is dry and bare in the sun. Explain how that could make the two lists so different."],key:["10. Three reeds and rushes, two snails, one frog, one heron, one water beetle and two willows.","the wet riverbank","The bank has water all the time and soft soil for roots, so many kinds of plant can grow and many kinds of animal find food and damp places to live. The wall top is dry, hot and bare, so only the toughest few can hang on. Listen for the link between what a place gives and what lives there."]}]},{id:23,title:"One Night, or a Canyon",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about this river, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>the town water office record</td><td>On one night of high water the bank below the bridge fell in, and by morning the path had lost three paces of ground.</td></tr>
     <tr><td>a display board at the gorge</td><td>This river has been cutting down through the rock for many thousands of years. That is how the gorge got so deep.</td></tr></table>`,qs:["Which note tells about a change that happened in one night?","Which note tells about a change that has taken many thousands of years?","Both notes are about water moving rock and soil. Name one more quick change to the land and one more slow one."],key:["The water office record, the bank falling in and three paces of path lost in one night.","The display board at the gorge, the river cutting down through rock for many thousands of years.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over. Slow: a cliff wearing back, a hill wearing down, soil building up year by year. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">There is water all through this town, and not all of it is in the river.</p>
     <div class="figure">${ic("drop",80)}${ic("cloud",80)}${ic("snowflake",80)}</div>`,qs:["Name three places in or near this town where you would find water.","Most of the water on Earth is in the ocean and it is salty. Is the water in this river salty or fresh, and how would you know?","Sort these four into solid water and liquid water: the ice along the canal edge, the water in the river, the frost on the workshop roof, the rain in the gutter."],key:["Any three: the river, the canal, a well, the rain barrel, clouds, frost or ice, under the ground, the town pipes.","Fresh. You can tell because people and animals drink it and crops are watered with it, and salty water would kill the plants. Accept tasting it or boiling it away and finding no salt.","Solid: the ice along the canal edge and the frost on the roof. Liquid: the water in the river and the rain in the gutter."]}]},{id:24,title:"Holding the Bank, and a Map of the Town",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things built to stop water from washing the land away",html:()=>`<p class="big">The river keeps eating into the bank beside the footpath. The town tried two ways to hold it and measured how much bank was lost in a year.</p>
     <table class="bigTable"><tr><th>What was put along the bank</th><th>Bank lost in one year</th></tr>
     <tr><td>nothing</td><td>60 centimeters</td></tr>
     <tr><td>a facing of heavy stones</td><td>5 centimeters</td></tr>
     <tr><td>a row of willow stakes that grew roots</td><td>10 centimeters in the first year</td></tr></table>`,qs:["Which one held the bank best in that first year?","How do you know, using the numbers in the chart?","The willow roots get thicker every year and the stones stay as they are. What might the chart look like after ten years, and why?"],key:["the facing of heavy stones, with only 5 centimeters lost","Only 5 centimeters of bank was lost behind the stones, 10 centimeters behind the willows, and 60 centimeters where there was nothing. The reason must come from the numbers.","The willows might hold as well as the stones or better, because their roots keep growing and spreading through the soil, while the stones do not change. Any answer that uses the idea of roots growing counts. This is a prediction, so a sensible reason matters more than the number."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the town. Put in the hill with the clock tower on it, the flat market square, the river, and the lake the river runs into. Add a key that says which is which.</p>
     <div class="figure">${ic("mountain",88)}${ic("map",88)}${ic("clock",88)}</div>`,qs:["Draw your model map with the hill, the flat square, the river and the lake on it.","Show me your key. Which parts are land and which parts are water?","Is the lake a bigger body of water than the river or a smaller one? Name one bigger than both."],key:["All four on the page and told apart by shape or color: the hill as a bump or as rings, the square left flat, the river as a line, the lake as a closed shape the river reaches.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","A lake usually holds more water in one place, while a river is long and narrow. Bigger than both: the ocean. Accept a well explained answer either way for the first half."]}]},{id:25,title:"Sorting the Lantern Workshop",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things from the workshop bench, and what was noticed about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What was noticed</th></tr>
     <tr><td>a lantern shade</td><td>paper</td><td>thin, bends easily, light shines through it, tears easily</td></tr>
     <tr><td>a frame hoop</td><td>wire</td><td>hard, shiny, holds a bent shape</td></tr>
     <tr><td>a hanging bead</td><td>glass</td><td>hard, smooth, you can see through it</td></tr>
     <tr><td>a tie string</td><td>wool</td><td>soft, bends easily, fluffy</td></tr></table>`,qs:["Sort the four items into a hard group and a group that bends easily.","Two of them let light through. Which two, and which one of those two would you use for a shade?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the wire hoop and the glass bead. Bends easily: the paper shade and the wool string.","The paper shade and the glass bead. The paper, because it is thin and bends so it can be shaped round a frame, and because light spreads through it instead of going straight through like glass.","Any property that can be seen or felt and that really splits the four: tears easily or does not, shiny or dull, soft or hard, holds a bent shape or does not. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The workshop needs a shade material for lanterns that hang outside along the river path. Three materials were tested on the same lamp, outside, through one damp evening.</p>
     <table class="bigTable"><tr><th>Material</th><th>How bright the glow was</th><th>After one damp evening</th></tr>
     <tr><td>thick card</td><td>dim</td><td>fine, no damage</td></tr>
     <tr><td>thin paper</td><td>bright</td><td>gone soft and torn</td></tr>
     <tr><td>waxed paper</td><td>bright</td><td>fine, no damage</td></tr></table>`,qs:["Which material should the outdoor shades be made of?","Which two pieces of the chart make you sure?","The thick card came through the damp evening perfectly well. Why is it still not the right choice?"],key:["the waxed paper","The glow was bright through it and it had no damage after a damp evening. Both columns have to be used, not just one.","The glow through it is dim, so the lantern hardly lights the path. It lasts well but it does not do the job the lantern is for."]}]},{id:26,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">A lantern frame is made of wire. It has 12 short pieces. It has 8 ties. One of the makers undid every tie. He laid the wire out straight. It lay on the bench.</p>
     <div class="figure">${ic("lantern",88)}${ic("board",88)}</div>`,qs:["The frame is gone. Are the wire pieces gone too? What is on the bench now?","Build something new in your head out of those 12 wire pieces and 8 ties. What is it, and how do the pieces go together?"],key:["No. All 12 wire pieces and all 8 ties are still there. They are the same pieces, just not tied together as a lantern frame any more.","Any real thing from 12 wire pieces and 8 ties: a star, a basket, a bird feeder hook, a spinner for the wind, a frame for a paper fish, a plant support. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened in the workshop on the same evening.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A block of candle wax was warmed in a tin and ran into a smooth pool.</td></tr>
     <tr><td>A sheet of paper was left leaning on the hot lamp and went brown and brittle.</td></tr></table>
     <div class="figure">${ic("lantern",80)}${ic("pan",80)}</div>`,qs:["Take the tin of melted wax off the heat and let it stand overnight. What happens to it?","Take the brown brittle paper away from the lamp and let it stand overnight. Does it go back to white paper?","Which of the two changes can be undone, and what is your evidence?"],key:["It goes hard again and is a block of wax, the shape of the tin.","No. It stays brown and brittle. Cooling does nothing for it.","The wax change can be undone. The evidence is that the wax goes hard again when it cools and melts again when it is warmed, while the browned paper never goes back however long it stands. Listen for the student using what happened, not just saying yes or no."]}]},{id:27,title:"The Lanterns That Tangle",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The paper lanterns hang from a long line. The line is above the river path. Each one hangs on a short piece of string. The wind comes up the river. The lanterns spin. By evening the strings are twisted. They twist round each other. Three or four lanterns are bunched. They end in a knot.</p>`,qs:["What is the problem the makers want to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The lanterns spin in the wind and their strings twist together into a knot. Naming the spinning and twisting, not the untangling, is the problem.","Any real question: how long are the strings, how far apart are the lanterns, how heavy is a lantern, which way does the wind come, how high is the line. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would stop the lanterns twisting round each other. Think hard about its shape.</p>
     <div class="figure">${ic("lantern",88)}${ic("board",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew stops the twisting."],key:["Any design that could really work: a stiff rod or arm instead of a string, two strings in a V from the line, a little weight hanging under each lantern, a hoop that each lantern sits in, bigger gaps along the line.","The shape is the part being checked. Something like: a stiff rod cannot twist, a V holds it facing one way, a weight underneath pulls it straight down, a hoop keeps it in its own circle."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both fixes were hung on the same line on two windy evenings, 20 lanterns each time.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Lanterns tangled by the end</th><th>Lanterns damaged</th></tr>
     <tr><td>a stiff rod holding each lantern</td><td>0</td><td>0</td></tr>
     <tr><td>a small weight under each lantern</td><td>3</td><td>2</td></tr></table>`,qs:["Which fix worked better?","How do you know? Use both columns."],key:["the stiff rod holding each lantern","No lanterns tangled and none were damaged with the rods, while 3 tangled and 2 were damaged with the weights. Both columns have to be used, not just the tangling."]}]},{id:28,title:"Telling the Time, Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the board under the clock tower.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>Yesterday the workshop finished the last of the hundred lanterns.</td></tr>
     <tr><td>2</td><td>Before there were clocks in houses, this bell was rung so the whole town would know the hour.</td></tr>
     <tr><td>3</td><td>This morning the clock in the tower was wound, the way it is every Monday.</td></tr>
     <tr><td>4</td><td>Long ago, goods came to this town on flat boats pulled along the canal by horses.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Think about a parent, a grandparent or a guardian of yours when they were your age. Name one thing about their day that was the same as yours, and one thing that was different."],key:["Lines 2 and 4, ringing the bell so the town knew the hour and horses pulling boats along the canal.","Lines 1 and 3, finishing the lanterns yesterday and winding the clock this morning.","Any true pair. Same: going to school, eating breakfast, doing chores, playing outside, having homework. Different: no phone or no screen at home, walking further to school, fewer cars, a different kind of television or none, different games, a different town or country. Both halves are what is being checked, since comparing their day with a grown-up’s is this standard’s second part. (HSS-2.1)"]}]},{id:29,title:"Where Things Are in the Town",short:"Town Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The town, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("mountain",46)} the hill</td><td>${ic("clock",46)} clock tower</td><td>${ic("pine",46)} park</td></tr>
     <tr><th>B</th><td>${ic("lantern",46)} lantern shop</td><td>${ic("coin",46)} market square</td><td>${ic("books",46)} library</td></tr>
     <tr><th>C</th><td>${ic("bridge",46)} stone bridge</td><td>${ic("wave",46)} the river</td><td>${ic("canoe",46)} boat landing</td></tr></table>
     <p class="big">${ic("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>
     <p class="big">A second map on the wall shows the whole continent of North America. On it you can find three countries, Canada, the United States and Mexico; the Atlantic Ocean on the east side and the Pacific Ocean on the west; the five Great Lakes along the border with Canada; the Mississippi River running down the middle; and the Rocky Mountains, a long mountain range in the west.</p>
     <p class="big">Every good map carries five things: a <b>title</b> that says what it shows, a <b>legend</b> that says what the symbols mean, a <b>directional indicator</b> such as a compass rose, a <b>scale</b> that tells you how far an inch stands for, and a <b>date</b> that says when it was made.</p>`,qs:["Give the exact square the market square is in, using its letter and number.","What is directly north of the market square?","Is the lantern shop east or west of the library?","Look at the map of North America. Name the continent, two of its three countries, one of its two oceans, and the mountain range in the west."],key:["B2","the clock tower, in square A2","west. The lantern shop is in B1 and the library is in B3, so the lantern shop is to the left, which is west.","The continent is North America. Countries: any two of Canada, the United States, Mexico. Oceans: the Atlantic or the Pacific. The mountain range in the west is the Rocky Mountains. Accept the Great Lakes or the Mississippi River as extra credit. All four parts are what is being checked. (HSS-2.2)"]}]},{id:30,title:"Rules, Money and the Workshop",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling who makes rules at each level here, and how another country chooses a leader differently",html:()=>`<p class="big">The town has a council that meets in the market hall, and the people of the town elect it.</p>
     <div class="figure">${ic("flag",80)}${ic("hands",80)}</div>`,qs:["The town council votes 7 to 2 to put lights along the river path. What happens, and why?","Who makes the laws for the whole country we live in? The town council, or the people we vote for in Congress?","In some other countries the leader is a king or a queen who was born into the job. In our country, how do we get our leaders?"],key:["The lights go in. More council members voted for it than against it, and that is how a vote is decided.","the people we vote for in Congress. A town council makes rules only for its own town.","We vote for them. Any answer that says the people choose their leaders by voting counts."]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, spending a set amount, and naming a producer and a consumer",html:()=>`<p class="big">What the workshop offers at its market stall.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a paper lantern</td><td>55 cents</td></tr>
     <tr><td>a spool of wick</td><td>20 cents</td></tr>
     <tr><td>a small candle</td><td>15 cents</td></tr>
     <tr><td>someone to mend your clock</td><td>40 cents</td></tr></table>
     <div class="figure">${ic("lantern",72)}${ic("clock",72)}</div>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","You have 50 cents. Name two things you could buy with it, and say what you give up.","The workshop makes the lanterns and you buy one. Which of you is the producer and which is the consumer?"],key:["Mending your clock. It is work someone does for you, not a thing you take away.","Any pair at 50 cents or less: wick and a candle is 35 cents, two candles is 30 cents, the clock mending on its own is 40 cents. A lantern at 55 cents is too much. The giving up is the part to listen for.","The workshop is the producer, because it makes the lanterns. You are the consumer, because you buy and use one."]}]},{id:31,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about him. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Albert Einstein was a boy. He asked questions. Nobody around him could answer them. He wondered what you would see. You might ride along beside a beam of light. He did not do well at some schools. They wanted him to repeat things back. After university he could only get one job. It was checking papers. He worked in a patent office. He kept thinking in his spare time. He wrote his ideas down. They changed what everyone understood. It was about light, time and space. Later he moved to the United States. He taught at a university. He spoke up for peace. He spoke up for people being treated fairly.</p>
     <div class="figure">${ic("star",80)}${ic("question",80)}</div>`,qs:["What kind of question did Albert Einstein wonder about as a boy?","Which word fits him best from what you read: curious, bored, or unkind? Say why.","Name one way what he did made a difference to other people."],key:["What you would see if you could ride along beside a beam of light. Accept any answer about wondering how light or time works.","curious. Any reason taken from the text: he asked questions nobody could answer, he kept thinking in his spare time even when his job was checking papers.","Any answer from the text: his ideas changed what everyone understood about light, time and space, he taught at a university, he spoke up for peace and for fair treatment."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Night Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["reflection","invisible","electricity"].map(w=>`<p class="huge" style="font-size:clamp(2.4rem,8vw,4.4rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["reflection (re-flec-tion, with tion saying shun)","invisible (in-vis-i-ble)","electricity (e-lec-tric-i-ty)"]},3:{id:"L3",title:"Level Up: Show Me the Words",std:["RL.3.1"],needs:["RL.2.1"],n:2,dir:"Answer out loud. Then read the words from the story that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${NIGHT_WALK}</p><ol class="qlist"><li>How do you know it was very cold that night? Read the part of the story that shows it.</li><li>How do you know Juno had been waiting a long time for this night? Read the part that shows it.</li></ol>`,key:["Says it was freezing, and reads the line about two sweaters, or the line about her hands shaking in the cold.","Says she had been watching all week, and reads the line about the crew stringing ropes all week while Juno watched from the window."]},5:{id:"L5",title:"Level Up: Prove It",std:["RI.3.1"],needs:["RI.2.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${TWINKLE}</p><ol class="qlist"><li>How do you know the twinkle is not something the star itself is doing? Read the part of the text that shows it.</li><li>How do you know the air has to be moving for a star to twinkle? Read the part that shows your answer.</li></ol>`,key:["Says the star shines steadily and the air does the bending, and reads the line that a star does not blink, or the line that the twinkle happens in the air above your head.","Reads the line about the moving air sliding past and bending the thin beam of starlight this way and that. Astronauts above the air see no twinkle, which backs it up."]},6:{id:"L6",title:"Level Up: Grown-Up Grammar",std:["L.3.1"],needs:["L.2.1"],n:2,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>One lantern is bright. A whole rope of them is ____ than one lantern.</li><li>Join these two sentences with the word <b>although</b>: The wind was cold. We stayed on the bridge.</li></ol>`,key:["brighter (the comparative form)","Although the wind was cold, we stayed on the bridge. (Or: We stayed on the bridge although the wind was cold.)"]},10:{id:"L10",title:"Level Up: How Long Did It Take",std:["3.MD.A.1"],needs:["2.MD.C.7"],n:2,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The crew started hanging lanterns at 4:25 p.m. and finished at 5:10 p.m.</p><ol class="qlist"><li>How many minutes did the work take?</li><li>The next night they started at 4:40 p.m. and worked for 50 minutes. What time did they finish?</li></ol>`,key:["45 minutes (4:25 to 5:00 is 35 minutes, then 5:00 to 5:10 is 10 more)","5:30 p.m. (4:40 plus 20 minutes is 5:00, plus 30 more is 5:30)"]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","RL.3.1","RI.3.1","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""],blk=[0,0,0];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}const STARTERS={"W.2.3":["One night, ____.","First, ____.","Then, ____.","After that, ____.","In the end, ____."],"W.2.8":["The log says ____.","On Monday the crew hung ____.","The most lanterns went up on ____.","I remember ____."],"W.2.1":["I would rather ____.","I think this because ____.","Also, ____.","That is why I would rather ____."],"W.2.2":["This is about ____.","A ____ is ____.","One fact is ____.","Now you know ____."]};const SENTLAB={"W.2.1":"If you are writing what you think:","W.2.2":"If you are writing facts:","W.2.3":"If you are telling a story:","W.2.8":"If you are using the log:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{if(STARTERS[c]&&sets.indexOf(c)<0)sets.push(c)}));if(!sets.length)sets.push("W.2.3");return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsCoinHtml(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(([k,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.coin(k)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`}function tpsClockHtml(){return`<div style="text-align:center;margin:8px 0"><img alt="A clock face. The short red hour hand points to the 10. The long blue minute hand points to the 12. Big numbers 1 to 12 are the hours. Small labels around the edge count minutes by fives, from :00 to :55." src="data:image/webp;base64,${window.TP_IMG1.wp.clocklab}" style="width:340px;max-width:100%;height:auto"></div>`+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},coins:{name:"Coin values",std:["2.MD.C.8"],html:tpsCoinHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart shows the counting sequence, so counting and skip-counting done with it is supported, not independent."},{t:"chart",std:["2.OA.A.1"],msg:"With the 120 chart the student can count on or back square by square. Note it if the answer came from counting by ones."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count those items as supported, not independent."},{t:"pv",std:["2.NBT.B.7"],msg:"The place value chart lines the digits up by place, which is most of the work in a written method. Note it."},{t:"blocks",std:["2.NBT.B.7","2.NBT.A.1"],msg:"If you built the numbers with blocks for the student, the item shows they can trade with a model, not that they can use a written method on their own."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"chart",std:["2.OA.C.3"],msg:"On the 120 chart a student can read off which numbers are even by their pattern instead of pairing. Note whether the reason given was about pairs or about the chart."},{t:"chart",std:["2.MD.C.8"],msg:"The 120 chart lets the student count up in cents square by square. Note it if the money answer came from counting rather than from knowing the coin values."},{t:"scribe",std:["W.2.1","W.2.2"],msg:"If an adult wrote the sentences for the student, the opinion, the reason and the facts still count. The printing and the spelling do not."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
